# Helper for structured reading of values from a RustBuffer.
class RustBufferStream

  def initialize(rbuf)
    @rbuf = rbuf
    @offset = 0
  end

  def remaining
    @rbuf.len - @offset
  end

  def read(size)
    raise InternalError, 'read past end of rust buffer' if @offset + size > @rbuf.len

    data = @rbuf.data.get_bytes @offset, size

    @offset += size

    data
  end

  def read_u8
    unpack_from 1, 'c'
  end

  def read_u16
    unpack_from 2, 'S>'
  end

  def read_u32
    unpack_from 4, 'L>'
  end

  def read_u64
    unpack_from 8, 'Q>'
  end

  def read_bool
    v = unpack_from 1, 'c'

    return false if v == 0
    return true if v == 1

    raise InternalError, 'Unexpected byte for Boolean type'
