# Helper for structured writing of values into a RustBuffer.
class RustBufferBuilder
  def initialize
    @rust_buf = RustBuffer.alloc 16
    @rust_buf.len = 0
  end

  def finalize
    rbuf = @rust_buf

    @rust_buf = nil

    rbuf
  end

  def discard
    return if @rust_buf.nil?

    rbuf = finalize
    rbuf.free
  end

  def write(value)
    reserve(value.bytes.size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, value.bytes
    end
  end

  def write_u8(v)
    v = ::FiremqClientFfi::uniffi_in_range(v, "u8", 0, 2**8)
    pack_into(1, 'c', v)
  end

  def write_u16(v)
    v = ::FiremqClientFfi::uniffi_in_range(v, "u16", 0, 2**16)
    pack_into(2, 'S>', v)
  end

  def write_u32(v)
    v = ::FiremqClientFfi::uniffi_in_range(v, "u32", 0, 2**32)
    pack_into(4, 'L>', v)
  end

  def write_u64(v)
    v = ::FiremqClientFfi::uniffi_in_range(v, "u64", 0, 2**64)
    pack_into(8, 'Q>', v)
  end

  def write_bool(v)
    pack_into(1, 'c', v ? 1 : 0)
  end

  def write_string(v)
    v = ::FiremqClientFfi::uniffi_utf8(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  def write_bytes(v)
    v = ::FiremqClientFfi::uniffi_bytes(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  # The Object type Client.

  def write_TypeClient(obj)
    handle = Client.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Object type Delivery.

  def write_TypeDelivery(obj)
    handle = Delivery.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Object type Subscription.

  def write_TypeSubscription(obj)
    handle = Subscription.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Record type MessageProperties.

  def write_TypeMessageProperties(v)
    self.write_Optionalstring(v.content_type)
    self.write_Optionalstring(v.content_encoding)
    self.write_Optionalstring(v.correlation_id)
    self.write_Optionalstring(v.reply_to)
    self.write_Optionalu64(v.expiration)
    self.write_Optionalstring(v.message_id)
    self.write_Optionalu64(v.timestamp)
    self.write_Optionalstring(v.message_type)
    self.write_Optionalstring(v.user_id)
    self.write_Optionalstring(v.app_id)
    self.write_Optionalu8(v.priority)
  end

  # The Record type PublishOptions.

  def write_TypePublishOptions(v)
    self.write_bool(v.persistent)
    self.write_bool(v.mandatory)
    self.write_bool(v.confirm)
    self.write_TypeMessageProperties(v.properties)
    self.write_Optionalstring(v.headers_json)
  end

  # The Record type QueueInfo.

  def write_TypeQueueInfo(v)
    self.write_string(v.name)
    self.write_u64(v.messages)
    self.write_u32(v.consumers)
  end

  # The Error type FireMqError - write for callback error returns.

  def write_TypeFireMqError(v)
    if v.is_a?(FireMqError::Server)
