        self.write_u16(v.code)
        self.write_string(v.message)
      return
    end
    if v.is_a?(FireMqError::Unroutable)
      pack_into 4, 'l>', 2
        self.write_string(v.message)
      return
    end
    if v.is_a?(FireMqError::Nacked)
      pack_into 4, 'l>', 3
        self.write_u16(v.code)
        self.write_string(v.message)
      return
    end
    if v.is_a?(FireMqError::Closed)
      pack_into 4, 'l>', 4
        self.write_string(v.message)
      return
    end
    if v.is_a?(FireMqError::Other)
      pack_into 4, 'l>', 5
        self.write_string(v.message)
      return
    end
  end
  

  # The Optional<T> type for u8.

  def write_Optionalu8(v)
    if v.nil?
      pack_into(1, 'c', 0)
    else
      pack_into(1, 'c', 1)
      self.write_u8(v)
    end
  end

  # The Optional<T> type for u64.

  def write_Optionalu64(v)
    if v.nil?
      pack_into(1, 'c', 0)
    else
      pack_into(1, 'c', 1)
      self.write_u64(v)
    end
  end

  # The Optional<T> type for string.

  def write_Optionalstring(v)
