  # Record type MessageProperties
class MessageProperties
  attr_reader :content_type, :content_encoding, :correlation_id, :reply_to, :expiration, :message_id, :timestamp, :message_type, :user_id, :app_id, :priority

  def initialize(content_type: nil, content_encoding: nil, correlation_id: nil, reply_to: nil, expiration: nil, message_id: nil, timestamp: nil, message_type: nil, user_id: nil, app_id: nil, priority: nil)
    @content_type = content_type
    @content_encoding = content_encoding
    @correlation_id = correlation_id
    @reply_to = reply_to
    @expiration = expiration
    @message_id = message_id
    @timestamp = timestamp
    @message_type = message_type
    @user_id = user_id
    @app_id = app_id
    @priority = priority
  end

  def ==(other)
    if @content_type != other.content_type
      return false
    end
    if @content_encoding != other.content_encoding
      return false
    end
    if @correlation_id != other.correlation_id
      return false
    end
    if @reply_to != other.reply_to
      return false
    end
    if @expiration != other.expiration
      return false
    end
    if @message_id != other.message_id
      return false
    end
    if @timestamp != other.timestamp
      return false
    end
    if @message_type != other.message_type
      return false
    end
    if @user_id != other.user_id
      return false
    end
    if @app_id != other.app_id
      return false
    end
    if @priority != other.priority
      return false
    end

    true
  end
  
end
  
  # Record type PublishOptions
class PublishOptions
  attr_reader :persistent, :mandatory, :confirm, :properties, :headers_json

  def initialize(persistent: true, mandatory: false, confirm: true, properties: MessageProperties.new, headers_json: nil)
    @persistent = persistent
    @mandatory = mandatory
    @confirm = confirm
    @properties = properties
    @headers_json = headers_json
  end

  def ==(other)
    if @persistent != other.persistent
      return false
    end
    if @mandatory != other.mandatory
      return false
    end
    if @confirm != other.confirm
      return false
    end
    if @properties != other.properties
      return false
    end
    if @headers_json != other.headers_json
      return false
    end

    true
  end
  
end
  
  # Record type QueueInfo
class QueueInfo
  attr_reader :name, :messages, :consumers

  def initialize(name:, messages:, consumers:)
    @name = name
    @messages = messages
    @consumers = consumers
  end

  def ==(other)
    if @name != other.name
      return false
    end
    if @messages != other.messages
      return false
    end
    if @consumers != other.consumers
      return false
    end

    true
  end
  
end
  

  

  
  class Client

  # A private helper for initializing instances of the class from a raw handle,
  # bypassing any initialization logic and ensuring they are GC'd properly.
  def self.uniffi_allocate(handle)
    inst = allocate
    inst.instance_variable_set :@handle, handle
    ObjectSpace.define_finalizer(inst, uniffi_define_finalizer_by_handle(handle, inst.object_id))
    return inst
  end

  # A private helper for registering an object finalizer.
  # N.B. it's important that this does not capture a reference
  # to the actual instance, only its underlying handle.
  def self.uniffi_define_finalizer_by_handle(handle, object_id)
    Proc.new do |_id|
      ::FiremqClientFfi.rust_call(
        :uniffi_firemq_client_ffi_fn_free_client,
        handle
      )
    end
  end
  # A private helper for lowering instances into a raw handle.
  # This does an explicit typecheck, because accidentally lowering a different type of
  # object in a place where this type is expected, could lead to memory unsafety.
  def self.uniffi_check_lower(inst)
    if !inst.is_a? self
      raise TypeError.new "Expected a Client instance, got #{inst}"
    end
  end

  def uniffi_clone_handle()
    return ::FiremqClientFfi.rust_call(
      :uniffi_firemq_client_ffi_fn_clone_client,
      @handle
    )
  end

  def self.uniffi_lower(inst)
    return inst.uniffi_clone_handle()
  end

  def self.uniffi_lift(handle)
    uniffi_allocate handle
